<?php
function rows\(string $file, int $cols\): void {
    $h = file_get_contents\($file\);
    if \(!preg_match_all\('#<tbody>\(.*?\)</tbody>#s', $h, $bodies\)\) { echo "no tbody\\n"; return; }
    $out = 0;
    foreach \($bodies[1] as $body\) {
        preg_match_all\('#<tr[^>]*>\(.*?\)</tr>#s', $body, $tr\);
        foreach \($tr[1] as $row\) {
            preg_match_all\('#<td[^>]*>\(.*?\)</td>#s', $row, $tds\);
            if \($tds[1] === []\) continue;
            $clean = array_map\(static fn\($c\) => trim\(preg_replace\('#\\s+#', ' ', preg_replace\('#<[^>]*>#', '', $c\)\)\), $tds[1]\);
            echo implode\(' | ', array_slice\($clean, 0, $cols\)\), "\\n";
            $out++;
            if \($out > 12\) return;
        }
    }
}
echo "=== CATEGORIES ===\\n"; rows\('/tmp/cats.html', 7\);
